mapper.select:
select
a.dict_id,
a.dict_code,
a.col_name,
a.dict_note,
a.up_dict,
a.remark,
a.sort
from t_dict_business a
where 1 = 1
 and a.dict_id = #{dictId, jdbcType=INTEGER}
 and a.dict_code = #{dictCode, jdbcType=VARCHAR}
 and a.col_name LIKE CONCAT('%',#{colName, jdbcType=VARCHAR},'%')
 and a.dict_note = #{dictNote, jdbcType=VARCHAR}
 and a.up_dict = #{upDict, jdbcType=INTEGER}
 and a.remark = #{remark, jdbcType=VARCHAR}
 and a.sort = #{sort, jdbcType=BIGINT}

